@pytest.mark.asyncio
async def test_await_cancelled_task_propagates_caller_cancellation() -> None:
    child_cancelled = asyncio.Event()
    release_child = asyncio.Event()

    async def stubborn_child() -> None:
        try:
            await asyncio.Event().wait()
        except asyncio.CancelledError:
            child_cancelled.set()
            await release_child.wait()

    child = asyncio.create_task(stubborn_child())
    cleanup_tasks: set[asyncio.Task[None]] = set()
    waiter = asyncio.create_task(
        proxy_service._await_cancelled_task(
            child,
            timeout_seconds=10.0,
            label="stubborn test child",
            cleanup_tasks=cleanup_tasks,
        )
    )
    await asyncio.wait_for(child_cancelled.wait(), timeout=1.0)

    waiter.cancel()
    with pytest.raises(asyncio.CancelledError):
        await waiter
    assert cleanup_tasks

    release_child.set()
    await asyncio.wait_for(child, timeout=1.0)
    for _ in range(10):
        if not cleanup_tasks:
            break
        await asyncio.sleep(0)
    assert cleanup_tasks == set()


@pytest.mark.asyncio
async def test_await_cancelled_task_allows_outer_cancellation_cleanup_to_finish() -> None:
    cleanup_finished = asyncio.Event()

    async def cancelled_owner() -> None:
        child = asyncio.create_task(asyncio.Event().wait())
        try:
            await asyncio.Event().wait()
        finally:
            await proxy_service._await_cancelled_task(
                child,
                timeout_seconds=1.0,
                label="outer cancellation child",
            )
            cleanup_finished.set()

    owner = asyncio.create_task(cancelled_owner())
    await asyncio.sleep(0)
    owner.cancel()

    with pytest.raises(asyncio.CancelledError):
        await owner
    assert cleanup_finished.is_set()


@pytest.mark.asyncio
async def test_await_cancelled_task_defers_stubborn_child_cleanup() -> None:
    child_cancelled = asyncio.Event()
    release_child = asyncio.Event()

    async def stubborn_child() -> None:
        try:
            await asyncio.Event().wait()
        except asyncio.CancelledError:
            child_cancelled.set()
            await release_child.wait()

    child = asyncio.create_task(stubborn_child())
    cleanup_tasks: set[asyncio.Task[None]] = set()
    assert (
        await proxy_service._await_cancelled_task(
            child,
            timeout_seconds=0.001,
            label="stubborn cleanup",
            cleanup_tasks=cleanup_tasks,
        )
        is False
    )
    assert cleanup_tasks
    await asyncio.wait_for(child_cancelled.wait(), timeout=1.0)

    release_child.set()
    await asyncio.wait_for(child, timeout=1.0)
    for _ in range(10):
        if not cleanup_tasks:
            break
        await asyncio.sleep(0)
    assert cleanup_tasks == set()


@pytest.mark.asyncio
async def test_close_http_bridge_session_bounded_cancellation_keeps_close_task_tracked(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    service = proxy_service.ProxyService(cast(Any, nullcontext()))
    session = _make_bridge_session(key_value="close-cancel-continues")
    close_started = asyncio.Event()
    release_close = asyncio.Event()
    close_finished = asyncio.Event()
    close_cancelled = False

    async def close_http_bridge_session(target: proxy_service._HTTPBridgeSession) -> None:
        nonlocal close_cancelled
        assert target is session
        close_started.set()
        try:
            await release_close.wait()
        except asyncio.CancelledError:
            close_cancelled = True
            raise
        finally:
            close_finished.set()

    monkeypatch.setattr(service, "_close_http_bridge_session", close_http_bridge_session)
    bounded_task = asyncio.create_task(service._close_http_bridge_session_bounded(session, reason="test"))
    await asyncio.wait_for(close_started.wait(), timeout=1.0)

    bounded_task.cancel()
    with pytest.raises(asyncio.CancelledError):
        await bounded_task

    assert close_cancelled is False
    assert service._background_cleanup_tasks
    release_close.set()
    await asyncio.wait_for(close_finished.wait(), timeout=1.0)
    for _ in range(10):
        if not service._background_cleanup_tasks:
            break
        await asyncio.sleep(0)
    assert service._background_cleanup_tasks == set()
    assert close_cancelled is False


